// Package gen emits Go source from a resolved workspace.
package gen

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
	"strconv"
	"strings"
)

// Header marks generated files. Tools and reviewers both key off this exact
// line, and it carries no timestamp or version so that regenerating unchanged
// input produces a byte-identical file.
const Header = "// Code generated by go-api-gen. DO NOT EDIT."

// File accumulates a Go source file and the imports its body needs.
type File struct {
	Package string
	Source  string // the spec this file was generated from, for the header

	imports map[string]string // import path -> qualifier
	buf     bytes.Buffer

	// redirect, when set, receives writes instead of buf.
	redirect *strings.Builder
}

// write appends to whichever buffer is active.
func (f *File) write(s string) {
	if f.redirect != nil {
		f.redirect.WriteString(s)
		return
	}
	f.buf.WriteString(s)
}

// NewFile returns a File for the given package.
func NewFile(pkg, source string) *File {
	return &File{Package: pkg, Source: source, imports: map[string]string{}}
}

// Import records an import and returns the qualifier to write before a symbol.
// The qualifier is derived from the last path segment, which is right for the
// overwhelming majority of packages; use ImportAs when it is not.
func (f *File) Import(path string) string {
	if path == "" {
		return ""
	}
	return f.ImportAs(path, defaultQualifier(path))
}

// ImportAs records an import that must be reachable under a specific
// qualifier, which is what a configured x-go-type such as uuid.UUID needs.
func (f *File) ImportAs(path, qualifier string) string {
	if path == "" {
		return ""
	}
	if prev, ok := f.imports[path]; ok {
		return prev
	}
	// Two different paths wanting the same qualifier would produce code that
	// does not compile, so the later one is suffixed.
	taken := map[string]bool{}
	for _, q := range f.imports {
		taken[q] = true
	}
	q := qualifier
	for i := 2; taken[q]; i++ {
		q = fmt.Sprintf("%s%d", qualifier, i)
	}
	f.imports[path] = q
	return q
}

// ImportType records the import a type expression needs and returns the
// expression unchanged, so a caller can write f.ImportType(t) inline.
func (f *File) ImportType(expr, path string) string {
	if path == "" {
		return expr
	}
	qualifier, _, ok := strings.Cut(expr, ".")
	if !ok {
		// A type with an import but no qualifier is imported for its side
		// effect on the expression, so fall back to the path's own name.
		f.Import(path)
		return expr
	}
	f.ImportAs(path, qualifier)
	return expr
}

// P writes a formatted line to the body.
func (f *File) P(layout string, args ...any) {
	if len(args) > 0 {
		f.write(fmt.Sprintf(layout, args...))
	} else {
		f.write(layout)
	}
	f.write("\n")
}

// commentWidth is where a generated doc comment wraps. Generated files are
// exempt from the line-length linter, but a paragraph that runs off the screen
// is no easier to read for being machine-written.
const commentWidth = 77

// Comment writes text as a doc comment, wrapping long paragraphs and skipping
// empty input so that a schema without a description produces no stray "//".
func (f *File) Comment(text string) {
	for _, para := range strings.Split(strings.TrimRight(text, "\n"), "\n") {
		if para == "" {
			f.P("//")
			continue
		}
		line := "//"
		for _, word := range strings.Fields(para) {
			if len(line)+1+len(word) > commentWidth && line != "//" {
				f.P("%s", line)
				line = "// " + word
				continue
			}
			line += " " + word
		}
		f.P("%s", line)
	}
}

// WriteRaw appends already-rendered source to the body.
func (f *File) WriteRaw(src string) { f.write(src) }

// SwapBuffer redirects writes to another buffer and returns the previous one.
//
// An emitter that discovers declarations while walking, such as the regular
// expressions a validator needs, renders the methods aside and then writes the
// declarations ahead of them.
func (f *File) SwapBuffer(next *strings.Builder) *bytes.Buffer {
	prev := f.buf
	f.buf = bytes.Buffer{}
	f.redirect = next
	return &prev
}

// RestoreBuffer undoes SwapBuffer.
func (f *File) RestoreBuffer(prev *bytes.Buffer) {
	f.redirect = nil
	f.buf = *prev
}

// Empty reports whether anything has been written to the body.
func (f *File) Empty() bool { return f.buf.Len() == 0 }

// Bytes renders the complete file and formats it.
func (f *File) Bytes() ([]byte, error) {
	var out bytes.Buffer
	out.WriteString(Header + "\n")
	if f.Source != "" {
		fmt.Fprintf(&out, "// Source: %s\n", f.Source)
	}
	out.WriteString("\n")
	fmt.Fprintf(&out, "package %s\n\n", f.Package)

	if len(f.imports) > 0 {
		out.WriteString("import (\n")
		std, ext := splitImports(f.imports)
		writeImports(&out, std, f.imports)
		if len(std) > 0 && len(ext) > 0 {
			out.WriteString("\n")
		}
		writeImports(&out, ext, f.imports)
		out.WriteString(")\n\n")
	}
	out.Write(f.buf.Bytes())

	src, err := format.Source(out.Bytes())
	if err != nil {
		// Returning the unformatted source alongside the error makes a
		// template bug diagnosable instead of just "expected declaration".
		return out.Bytes(), fmt.Errorf("generated code does not parse: %w", err)
	}
	return src, nil
}

func writeImports(
	out *bytes.Buffer,
	paths []string,
	qualifiers map[string]string,
) {
	for _, p := range paths {
		if q := qualifiers[p]; q != defaultQualifier(p) {
			fmt.Fprintf(out, "\t%s %s\n", q, strconv.Quote(p))
			continue
		}
		fmt.Fprintf(out, "\t%s\n", strconv.Quote(p))
	}
}

// splitImports separates the standard library from everything else, matching
// the grouping gofmt and goimports produce by convention.
func splitImports(imports map[string]string) (std, ext []string) {
	for p := range imports {
		if isStdlib(p) {
			std = append(std, p)
		} else {
			ext = append(ext, p)
		}
	}
	sort.Strings(std)
	sort.Strings(ext)
	return std, ext
}

// isStdlib reports whether an import path belongs to the standard library. A
// standard library path never has a dot in its first segment, since that is
// where a domain name would be.
func isStdlib(path string) bool {
	first, _, _ := strings.Cut(path, "/")
	return !strings.Contains(first, ".")
}

// defaultQualifier is the identifier a package is normally referred to by.
func defaultQualifier(path string) string {
	last := path
	if i := strings.LastIndex(path, "/"); i >= 0 {
		last = path[i+1:]
	}
	// A versioned suffix such as yaml.v3 is not part of the package name.
	if base, ver, ok := strings.Cut(
		last,
		".",
	); ok && strings.HasPrefix(ver, "v") {
		last = base
	}
	last = strings.ReplaceAll(last, "-", "")
	if last == "" {
		return "pkg"
	}
	return last
}
